del ZH[76]
del ZH[93]

# each dict must cover exactly the 123 nodes that have a French gist
FR = json.load(open(os.path.join(OUT, "fr.json"), encoding="utf-8"))
want = set(int(k) for k in FR)
for code, d in (("ru", RU), ("ar", AR), ("zh", ZH)):
    missing, extra = want - set(d), set(d) - want
    assert not missing, f"{code}: missing gists for {sorted(missing)}"
    assert not extra, f"{code}: unexpected node ids {sorted(extra)}"
    assert all(v.strip() for v in d.values()), f"{code}: has an empty gist"
    json.dump({str(k): d[k] for k in sorted(d)},
              open(os.path.join(OUT, f"{code}.json"), "w", encoding="utf-8"),
              ensure_ascii=False, separators=(",", ":"), sort_keys=True)

print(f"ru/ar/zh gists: {len(RU)}/{len(AR)}/{len(ZH)} each "
      f"(whole book, machine-authored — pending native review)")
